#include <vector>

template <typename T>
struct Box {
  std::vector<T> items;
  int Count() const { return static_cast<int>(items.size()); }
};

int main(int argc, char** argv) {
  Box<int> box{{1, 2, 3}};
  if (argc > 1 && argv[1][0] == '-') {
    return box.Count() << 2;  // shift
  }
  return 0;
}

def fib(n: int) -> list[int]:
    """Return the first n Fibonacci numbers."""
    out = [0, 1]
    while len(out) < n:
        out.append(out[-1] + out[-2])
    return out[:n]


